        except FileNotFoundError:
            return 0
        except (OSError, ValueError):
            raise _LedgerCorrupt from None
        if not isinstance(data, dict) or set(data) != {"day", "spent_usd"} or not isinstance(data["day"], str):
            raise _LedgerCorrupt
