        else:
            pos += 1
        key = (kind, ref, cand)
        if key in seen:
            _bad(i, 'DUPLICATE')
        seen.add(key)
    if pos < MIN_ROWS:
        raise ManifestError('manifest: TOO_FEW_POSITIVE')
    if neg < MIN_ROWS:
        raise ManifestError('manifest: TOO_FEW_DIFFERENT')


